// FromJSON parses a JSON string and returns a Theme.
// On parse error, returns the default theme along with the error.
func FromJSON(data string) (fyne.Theme, error) {
	return FromJSONReader(strings.NewReader(data))
}

// FromJSONReader parses JSON from an io.Reader and returns a Theme.
// On parse error, returns the default theme along with the error.
func FromJSONReader(r io.Reader) (fyne.Theme, error) {
	var raw map[string]interface{}
	decoder := json.NewDecoder(r)
	if err := decoder.Decode(&raw); err != nil {
		return DarkTheme(), fmt.Errorf("failed to parse JSON: %w", err)
	}

	jt := &jsonTheme{
		colors:      make(map[fyne.ThemeColorName]color.Color),
		colorsDark:  make(map[fyne.ThemeColorName]color.Color),
		colorsLight: make(map[fyne.ThemeColorName]color.Color),
		sizes:       make(map[fyne.ThemeSizeName]float32),
		fonts:       make(map[string]fyne.Resource),
		icons:       make(map[fyne.ThemeIconName]fyne.Resource),
		fallback:    DarkTheme(),
	}

	// Parse generic colors
	if colorsMap, ok := raw["Colors"].(map[string]interface{}); ok {
		for name, value := range colorsMap {
			if hexStr, ok := value.(string); ok {
				c, err := parseHexColor(hexStr)
				if err == nil {
					jt.colors[fyne.ThemeColorName(name)] = c
				}
			}
		}
	}

	// Parse dark variant colors
	if colorsMap, ok := raw["Colors-dark"].(map[string]interface{}); ok {
		for name, value := range colorsMap {
			if hexStr, ok := value.(string); ok {
				c, err := parseHexColor(hexStr)
				if err == nil {
					jt.colorsDark[fyne.ThemeColorName(name)] = c
				}
			}
		}
	}

	// Parse light variant colors
	if colorsMap, ok := raw["Colors-light"].(map[string]interface{}); ok {
		for name, value := range colorsMap {
			if hexStr, ok := value.(string); ok {
				c, err := parseHexColor(hexStr)
				if err == nil {
					jt.colorsLight[fyne.ThemeColorName(name)] = c
				}
			}
		}
	}

	// Parse sizes
	if sizesMap, ok := raw["Sizes"].(map[string]interface{}); ok {
		for name, value := range sizesMap {
			var size float32
			switch v := value.(type) {
			case float64:
				size = float32(v)
			case float32:
				size = v
			case int:
				size = float32(v)
			}
			if size > 0 {
				jt.sizes[fyne.ThemeSizeName(name)] = size
			}
		}
	}

	// Parse fonts
	if fontsMap, ok := raw["Fonts"].(map[string]interface{}); ok {
		for style, value := range fontsMap {
			if uriStr, ok := value.(string); ok {
				uri, err := storage.ParseURI(uriStr)
				if err == nil {
					// Store font resource by style name
					jt.fonts[style] = &uriResource{uri: uri}
				}
			}
		}
	}

	// Parse icons
	if iconsMap, ok := raw["Icons"].(map[string]interface{}); ok {
		for name, value := range iconsMap {
			if uriStr, ok := value.(string); ok {
				uri, err := storage.ParseURI(uriStr)
				if err == nil {
					jt.icons[fyne.ThemeIconName(name)] = &uriResource{uri: uri}
				}
			}
		}
	}

	return jt, nil
}

// parseHexColor parses a hex color string in various formats:
// 3 digits: "abc" -> 0xaa 0xbb 0xcc 0xff
// 4 digits: "abcd" -> 0xaa 0xbb 0xcc 0xdd
// 6 digits: "a1b2c3" -> 0xa1 0xb2 0xc3 0xff
// 8 digits: "a1b2c3f4" -> 0xa1 0xb2 0xc3 0xf4
// All formats support optional "#" prefix
func parseHexColor(s string) (color.Color, error) {
	s = strings.TrimSpace(s)
	s = strings.TrimPrefix(s, "#")

	var r, g, b, a uint8
	a = 255 // default alpha

	switch len(s) {
	case 3:
		// RGB format: expand each digit
		vals, err := parseHexDigits(s)
		if err != nil {
			return color.Transparent, err
		}
		r = vals[0]*16 + vals[0]
		g = vals[1]*16 + vals[1]
		b = vals[2]*16 + vals[2]

	case 4:
		// RGBA format: expand each digit
		vals, err := parseHexDigits(s)
		if err != nil {
			return color.Transparent, err
		}
		r = vals[0]*16 + vals[0]
		g = vals[1]*16 + vals[1]
		b = vals[2]*16 + vals[2]
		a = vals[3]*16 + vals[3]

	case 6:
		// RRGGBB format
		val, err := strconv.ParseUint(s, 16, 32)
		if err != nil {
			return color.Transparent, fmt.Errorf("invalid hex color: %s", s)
		}
		r = uint8((val >> 16) & 0xFF)
		g = uint8((val >> 8) & 0xFF)
		b = uint8(val & 0xFF)

	case 8:
		// RRGGBBAA format
		val, err := strconv.ParseUint(s, 16, 64)
		if err != nil {
			return color.Transparent, fmt.Errorf("invalid hex color: %s", s)
		}
		r = uint8((val >> 24) & 0xFF)
		g = uint8((val >> 16) & 0xFF)
		b = uint8((val >> 8) & 0xFF)
		a = uint8(val & 0xFF)

	default:
		return color.Transparent, fmt.Errorf("invalid hex color length: %s", s)
	}

	return color.NRGBA{R: r, G: g, B: b, A: a}, nil
}

func parseHexDigits(s string) ([]uint8, error) {
	vals := make([]uint8, len(s))
	for i, c := range s {
		var val uint8
		switch {
		case c >= '0' && c <= '9':
			val = uint8(c - '0')
		case c >= 'a' && c <= 'f':
			val = uint8(c - 'a' + 10)
		case c >= 'A' && c <= 'F':
			val = uint8(c - 'A' + 10)
		default:
			return nil, fmt.Errorf("invalid hex digit: %c", c)
		}
		vals[i] = val
	}
